def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    sep=next(v for v in Counter(v for row in grid for v in row) if any(all(x==v for x in grid[i]) for i in range(h)))
    seps_r=[i for i in range(h) if all(v==sep for v in grid[i])]
    seps_c=[j for j in range(w) if all(grid[i][j]==sep for i in range(h))]
    def blocks(seps,size):
        bs=[(0,seps[0])]
        for a,b in zip(seps,seps[1:]): bs.append((a+1,b))
        bs.append((seps[-1]+1,size))
        return bs
    rb=blocks(seps_r,h); cb=blocks(seps_c,w)
    def nonzero(bc):
        a,b=bc
        return any(grid[i][j]!=0 for i in range(rb[0][0],rb[0][1]) for j in range(a,b))
    tci=next(i for i,bc in enumerate(cb) if i>0 and nonzero(bc))
    t0,t1=cb[tci]
    tmpl=[[1 if grid[i][j]!=0 else 0 for j in range(t0,t1)] for i in range(rb[0][0],rb[0][1])]
    out=[row[:] for row in grid]
    for (r0,r1) in rb:
        a,b=cb[0]
        col=next((grid[i][j] for i in range(r0,r1) for j in range(a,b) if grid[i][j] not in (0,sep)),None)
        if col is None: continue
        for (c0,c1) in cb:
            for i in range(r0,r1):
                for j in range(c0,c1):
                    out[i][j]= col if tmpl[i-r0][j-c0] else 0
    return out
